-- 按 surface.name (lower-case) 索引：apply_blueprint 直接 O(1) 查表，
-- 不用线性遍历 + 字符串比较。同名行星支持多蓝图，所以 value 是 list
blueprint = {
    nauvis = {
        { level = 1, data = Nauvis,           pos = { x = 0, y = 0 }, direction = 0 },
        { level = 2, data = NauvisPower,      pos = { x = 0, y = 0 }, direction = 0 },
        { level = 3, data = NauvisMining,     pos = { x = 0, y = 0 }, direction = 0 },
        { level = 4, data = NauvisProduction, pos = { x = 0, y = 0 }, direction = 0 },
    },
    vulcanus = {
        { level = 1, data = Vulcanus,           pos = { x = 0, y = 0 }, direction = 0 },
        { level = 2, data = VulcanusPower,      pos = { x = 0, y = 0 }, direction = 0 },
        { level = 3, data = VulcanusMining,     pos = { x = 0, y = 0 }, direction = 0 },
        { level = 4, data = VulcanusProduction, pos = { x = 0, y = 0 }, direction = 0 },
    },
    fulgora = {
        { level = 1, data = Fulgora,           pos = { x = 0, y = 0 }, direction = 0 },
        { level = 2, data = FulgoraPower,      pos = { x = 0, y = 0 }, direction = 0 },
        { level = 3, data = FulgoraMining,     pos = { x = 0, y = 0 }, direction = 0 },
        { level = 4, data = FulgoraProduction, pos = { x = 0, y = 0 }, direction = 0 },
    },
    gleba = {
        { level = 1, data = Gleba,           pos = { x = 0, y = 0 }, direction = 0 },
        { level = 2, data = GlebaPower,      pos = { x = 0, y = 0 }, direction = 0 },
        { level = 3, data = GlebaMining,     pos = { x = 0, y = 0 }, direction = 0 },
        { level = 4, data = GlebaProduction, pos = { x = 0, y = 0 }, direction = 0 },
    },
    aquilo = {
        { level = 1, data = Aquilo,           pos = { x = 0, y = 0 }, direction = 0 },
        { level = 2, data = AquiloPower,      pos = { x = 0, y = 0 }, direction = 0 },
        { level = 3, data = AquiloMining,     pos = { x = 0, y = 0 }, direction = 0 },
        { level = 4, data = AquiloProduction, pos = { x = 0, y = 0 }, direction = 0 },
    },
}

return blueprint
